# More famous Welsh people, part C: the twentieth century and today. Politics, words, art, science.
# Same format and voice as people2a.py.
from people2a import P

PEOPLE = [
 P("billy-hughes", "modern", "1862–1952", "Billy Hughes", "Billy Hughes", "Welsh-speaking Prime Minister of Australia", "Prif Weinidog Cymraeg Awstralia", "Billy_Hughes", "politics",
   "Raised in Llandudno, the son of a Holyhead carpenter, he led Australia through the First World War as Prime Minister from 1915 to 1923.",
   "Fe’i magwyd yn Llandudno, yn fab i saer o Gaergybi, ac arweiniodd Awstralia drwy’r Rhyfel Byd Cyntaf yn Brif Weinidog o 1915 i 1923.",
   ["William Morris Hughes was born in London to Welsh parents and spent his boyhood in Llandudno, where he grew up speaking Welsh. At twenty-two he sailed to Australia, worked as a labourer and organised the dock workers.",
    "He became Prime Minister of Australia in 1915, led the country through the war and spoke for it at the peace conference at Versailles. He sat in the Australian parliament for fifty-one years, a record, and kept his Welsh to the end of his life."],
   ["Ganed William Morris Hughes yn Llundain i rieni o Gymry a threuliodd ei fachgendod yn Llandudno, lle tyfodd i fyny’n siarad Cymraeg. Yn ddwy ar hugain hwyliodd i Awstralia, gweithio’n labrwr a threfnu gweithwyr y dociau.",
    "Daeth yn Brif Weinidog Awstralia yn 1915, arwain y wlad drwy’r rhyfel a siarad drosti yng nghynhadledd heddwch Versailles. Eisteddodd yn senedd Awstralia am un mlynedd ar ddeg a deugain, record, a chadwodd ei Gymraeg hyd ddiwedd ei oes."]),
 P("lady-rhondda", "modern", "1883–1958", "Margaret, Lady Rhondda", "Margaret, Arglwyddes Rhondda", "Suffragette and publisher", "Swffragét a chyhoeddwraig", "Margaret_Mackworth,_2nd_Viscountess_Rhondda", "politics",
   "Suffragette from Llanwern who survived the Lusitania, founded the magazine Time and Tide and fought for women’s right to sit in the House of Lords.",
   "Swffragét o Lanwern a oroesodd suddo’r Lusitania, a sefydlodd y cylchgrawn Time and Tide ac a ymladdodd dros hawl menywod i eistedd yn Nhŷ’r Arglwyddi.",
   ["Margaret Haig Thomas grew up at Llanwern near Newport, the daughter of the coal owner D. A. Thomas. She led the suffragettes of Newport and in 1913 was jailed for setting fire to a post box, and went on hunger strike. In 1915 she survived the sinking of the Lusitania.",
    "She became a leading businesswoman, the first woman president of the Institute of Directors, and in 1920 founded Time and Tide, a weekly that championed women’s equality. She inherited her father’s title and fought for years for peeresses to sit in the Lords, a right women won in 1958, the year she died."],
   ["Magwyd Margaret Haig Thomas yn Llanwern ger Casnewydd, yn ferch i’r perchennog glo D. A. Thomas. Arweiniodd swffragetiaid Casnewydd ac yn 1913 fe’i carcharwyd am roi blwch post ar dân, ac aeth ar streic newyn. Yn 1915 goroesodd suddo’r Lusitania.",
    "Daeth yn wraig fusnes flaenllaw, y fenyw gyntaf yn llywydd Sefydliad y Cyfarwyddwyr, ac yn 1920 sefydlodd Time and Tide, wythnosolyn a hyrwyddai gydraddoldeb menywod. Etifeddodd deitl ei thad a brwydro am flynyddoedd i arglwyddesau gael eistedd yn Nhŷ’r Arglwyddi, hawl a enillodd menywod yn 1958, y flwyddyn y bu farw."],
   first=("wales", "The first woman president of the Institute of Directors, 1926", "Y fenyw gyntaf yn llywydd Sefydliad y Cyfarwyddwyr, 1926", 1926)),
 P("annie-hughes-griffiths", "modern", "1873–1942", "Annie Hughes Griffiths", "Annie Hughes Griffiths", "Leader of the women’s peace petition", "Arweinydd deiseb heddwch y menywod", "Annie_Hughes_Griffiths", "politics",
   "Led the peace appeal of the women of Wales, signed by 390,296 women, and carried it to the United States in 1924.",
   "Arweiniodd apêl heddwch menywod Cymru, a lofnodwyd gan 390,296 o fenywod, a’i chludo i’r Unol Daleithiau yn 1924.",
   ["After the slaughter of the First World War, the women of Wales resolved that it must never happen again. In 1923 Annie Hughes Griffiths of Aberystwyth led a campaign that went from door to door in every town and village, and 390,296 women signed an appeal to the women of America to join them in building peace through the League of Nations.",
    "The petition filled a great oak chest. Annie Hughes Griffiths and three companions carried it across the Atlantic in 1924, met President Coolidge and travelled the United States speaking for peace. The chest was kept at the Smithsonian in Washington for a century, and was brought home to Wales for the centenary in 2023."],
   ["Wedi lladdfa’r Rhyfel Byd Cyntaf penderfynodd menywod Cymru na ddylai ddigwydd byth eto. Yn 1923 arweiniodd Annie Hughes Griffiths o Aberystwyth ymgyrch a aeth o ddrws i ddrws ym mhob tref a phentref, a llofnododd 390,296 o fenywod apêl at fenywod America i ymuno â hwy i adeiladu heddwch drwy Gynghrair y Cenhedloedd.",
    "Llanwodd y ddeiseb gist dderw fawr. Cludodd Annie Hughes Griffiths a thair cydymaith hi dros yr Iwerydd yn 1924, cyfarfod â’r Arlywydd Coolidge a theithio’r Unol Daleithiau yn siarad dros heddwch. Cadwyd y gist yn y Smithsonian yn Washington am ganrif, a daethpwyd â hi adref i Gymru ar gyfer y canmlwyddiant yn 2023."]),
 P("roy-jenkins", "modern", "1920–2003", "Roy Jenkins", "Roy Jenkins", "Reforming statesman", "Gwladweinydd diwygiadol", "Roy_Jenkins", "politics",
   "Miner’s son from Abersychan who as Home Secretary changed Britain’s laws for a more tolerant society, and became the only British President of the European Commission.",
   "Mab glöwr o Abersychan a newidiodd gyfreithiau Prydain tuag at gymdeithas fwy goddefgar fel Ysgrifennydd Cartref, ac a fu’r unig Brydeiniwr yn Llywydd y Comisiwn Ewropeaidd.",
   ["Roy Jenkins was born in Abersychan in Monmouthshire, the son of a miners’ leader. As Home Secretary from 1965 he championed the reforms that ended theatre censorship, decriminalised homosexuality and outlawed racial discrimination, and made Britain a freer and more tolerant country.",
    "He was Chancellor of the Exchequer, then President of the European Commission from 1977 to 1981, the only Briton to hold the post. He was a founder of the Social Democratic Party, Chancellor of Oxford University and a celebrated biographer of Gladstone and Churchill."],
   ["Ganed Roy Jenkins yn Abersychan yn Sir Fynwy, yn fab i arweinydd y glowyr. Fel Ysgrifennydd Cartref o 1965 hyrwyddodd y diwygiadau a roddodd ben ar sensoriaeth y theatr, a ddad-droseddodd gyfunrywioldeb ac a waharddodd wahaniaethu hiliol, a gwneud Prydain yn wlad fwy rhydd a goddefgar.",
    "Bu’n Ganghellor y Trysorlys, ac yna’n Llywydd y Comisiwn Ewropeaidd o 1977 i 1981, yr unig Brydeiniwr i ddal y swydd. Roedd yn un o sylfaenwyr y Blaid Ddemocrataidd Gymdeithasol, yn Ganghellor Prifysgol Rhydychen ac yn gofiannydd enwog i Gladstone a Churchill."],
   first=("wales", "The only Briton ever to be President of the European Commission, 1977", "Yr unig Brydeiniwr erioed yn Llywydd y Comisiwn Ewropeaidd, 1977", 1977)),
 P("neil-kinnock", "modern", "born 1942", "Neil Kinnock", "Neil Kinnock", "Orator of Tredegar", "Areithiwr Tredegar", "Neil_Kinnock", "politics",
   "From Tredegar, the town of Aneurin Bevan, leader of the Labour Party for nine years and later Vice-President of the European Commission.",
   "O Dredegar, tref Aneurin Bevan; arweinydd y Blaid Lafur am naw mlynedd ac wedyn Is-lywydd y Comisiwn Ewropeaidd.",
   ["Neil Kinnock was born in Tredegar, the son of a miner, and became MP for Bedwellty in 1970. His speeches, full of the fire of the valleys, made him one of the great orators of his time.",
    "He led the Labour Party from 1983 to 1992 and rebuilt it into a party of government. He went on to serve as a European Commissioner and Vice-President of the European Commission, and later sat in the House of Lords."],
   ["Ganed Neil Kinnock yn Nhredegar, yn fab i löwr, a daeth yn AS Bedwellte yn 1970. Gwnaeth ei areithiau, yn llawn tân y cymoedd, ef yn un o areithwyr mawr ei oes.",
    "Arweiniodd y Blaid Lafur o 1983 i 1992 a’i hailadeiladu’n blaid lywodraeth. Aeth ymlaen i fod yn Gomisiynydd Ewropeaidd ac yn Is-lywydd y Comisiwn Ewropeaidd, ac eisteddodd wedyn yn Nhŷ’r Arglwyddi."]),
 P("dafydd-wigley", "modern", "born 1943", "Dafydd Wigley", "Dafydd Wigley", "Champion of disabled people", "Hyrwyddwr pobl anabl", "Dafydd_Wigley", "politics",
   "Plaid Cymru leader and MP for Caernarfon for 27 years, who wrote the law that opened public buildings to disabled people.",
   "Arweinydd Plaid Cymru ac AS Caernarfon am 27 mlynedd, a ysgrifennodd y gyfraith a agorodd adeiladau cyhoeddus i bobl anabl.",
   ["Dafydd Wigley was elected MP for Caernarfon in 1974 and served for twenty-seven years, leading Plaid Cymru twice. Two of his sons were born with a severe disability, and he made the cause of disabled people his own.",
    "His Disabled Persons Act of 1981 required new public buildings to be accessible to disabled people. He led Plaid Cymru into the first National Assembly in 1999, where it won seventeen seats, and was later made a life peer as Lord Wigley."],
   ["Etholwyd Dafydd Wigley yn AS Caernarfon yn 1974 a bu’n gwasanaethu am saith mlynedd ar hugain, gan arwain Plaid Cymru ddwywaith. Ganed dau o’i feibion ag anabledd difrifol, a gwnaeth achos pobl anabl yn achos iddo’i hun.",
    "Mynnodd ei Ddeddf Pobl Anabl 1981 fod adeiladau cyhoeddus newydd yn hygyrch i bobl anabl. Arweiniodd Blaid Cymru i’r Cynulliad Cenedlaethol cyntaf yn 1999, lle enillodd ddwy sedd ar bymtheg, ac fe’i gwnaed wedyn yn arglwydd am oes, yr Arglwydd Wigley."]),
 P("dafydd-elis-thomas", "today", "1946–2025", "Dafydd Elis-Thomas", "Dafydd Elis-Thomas", "First Presiding Officer", "Llywydd cyntaf", "Dafydd_Elis-Thomas", "politics",
   "The first Presiding Officer of the National Assembly for Wales, who chaired the Welsh parliament through its first twelve years.",
   "Llywydd cyntaf Cynulliad Cenedlaethol Cymru, a gadeiriodd senedd Cymru drwy ei deuddeng mlynedd cyntaf.",
   ["Dafydd Elis-Thomas was elected MP for Meirionnydd in 1974, at twenty-seven, and led Plaid Cymru from 1984 to 1991. As the first chairman of the Welsh Language Board from 1993 he put the new Welsh Language Act into practice.",
    "When the National Assembly first met in 1999 he was chosen as its Presiding Officer, and for twelve years he shaped how the new parliament worked, in both languages, and argued for it to win full law-making powers. He died in 2025."],
   ["Etholwyd Dafydd Elis-Thomas yn AS Meirionnydd yn 1974, yn saith ar hugain oed, ac arweiniodd Blaid Cymru o 1984 i 1991. Fel cadeirydd cyntaf Bwrdd yr Iaith Gymraeg o 1993 rhoddodd Ddeddf yr Iaith Gymraeg newydd ar waith.",
    "Pan gyfarfu’r Cynulliad Cenedlaethol gyntaf yn 1999 fe’i dewiswyd yn Llywydd, ac am ddeuddeng mlynedd lluniodd ffordd y senedd newydd o weithio, yn y ddwy iaith, a dadlau iddi ennill pwerau deddfu llawn. Bu farw yn 2025."],
   first=("wales", "The first Presiding Officer of the National Assembly for Wales, 1999", "Llywydd cyntaf Cynulliad Cenedlaethol Cymru, 1999", 1999)),
 P("julia-gillard", "today", "born 1961", "Julia Gillard", "Julia Gillard", "From Barry to the top in Australia", "O’r Barri i’r brig yn Awstralia", "Julia_Gillard", "politics",
   "Born in Barry, she became the first woman Prime Minister of Australia, from 2010 to 2013.",
   "Fe’i ganed yn y Barri a daeth yn Brif Weinidog benywaidd cyntaf Awstralia, o 2010 i 2013.",
   ["Julia Gillard was born in Barry in 1961. As a child she had bronchial pneumonia, and the doctors advised her parents that a warmer climate would help, so in 1966 the family emigrated to Adelaide.",
    "She became a lawyer and a Labor politician, and in June 2010 the first woman to be Prime Minister of Australia. Her government brought in a national disability insurance scheme and reforms to schools. Barry has welcomed her home with pride."],
   ["Ganed Julia Gillard yn y Barri yn 1961. Yn blentyn cafodd niwmonia, a chynghorodd y meddygon ei rhieni y byddai hinsawdd gynhesach yn helpu, felly yn 1966 ymfudodd y teulu i Adelaide.",
    "Daeth yn gyfreithiwr ac yn wleidydd Llafur, ac ym Mehefin 2010 y fenyw gyntaf i fod yn Brif Weinidog Awstralia. Cyflwynodd ei llywodraeth gynllun yswiriant anabledd cenedlaethol a diwygiadau i ysgolion. Mae’r Barri wedi’i chroesawu adref â balchder."],
   first=("wales", "Born in Barry: the first woman Prime Minister of Australia, 2010", "Ganed yn y Barri: Prif Weinidog benywaidd cyntaf Awstralia, 2010", 2010)),
 P("eluned-morgan", "today", "born 1967", "Eluned Morgan", "Eluned Morgan", "First woman First Minister", "Prif Weinidog benywaidd cyntaf", "Eluned_Morgan", "politics",
   "Welsh-speaking politician from Ely in Cardiff who in 2024 became the first woman to lead the government of Wales.",
   "Gwleidydd Cymraeg o Drelái yng Nghaerdydd ac yn 2024 hi oedd y fenyw gyntaf i arwain llywodraeth Cymru.",
   ["Eluned Morgan was born in Ely, Cardiff, the daughter of a minister, and was educated at Ysgol Gyfun Glantaf. In 1994, at twenty-seven, she became the youngest member of the European Parliament.",
    "She later sat in the House of Lords and in the Senedd, serving as minister for the Welsh language and for health. In August 2024 she became First Minister, the first woman to lead the government of Wales."],
   ["Ganed Eluned Morgan yn Nhrelái, Caerdydd, yn ferch i weinidog, a’i haddysgu yn Ysgol Gyfun Glantaf. Yn 1994, yn saith ar hugain oed, daeth yn aelod ieuengaf Senedd Ewrop.",
    "Eisteddodd wedyn yn Nhŷ’r Arglwyddi ac yn y Senedd, gan wasanaethu’n weinidog y Gymraeg ac iechyd. Ym mis Awst 2024 daeth yn Brif Weinidog, y fenyw gyntaf i arwain llywodraeth Cymru."],
   first=("wales", "The first woman First Minister of Wales, 2024", "Prif Weinidog benywaidd cyntaf Cymru, 2024", 2024)),
 P("w-h-davies", "modern", "1871–1940", "W. H. Davies", "W. H. Davies", "The Super-Tramp", "Y Crwydryn", "W._H._Davies", "words",
   "Newport poet who tramped across America, lost a leg jumping a train, and wrote ‘What is this life if, full of care, we have no time to stand and stare.’",
   "Bardd o Gasnewydd a fu’n crwydro America, a gollodd goes wrth neidio ar drên, ac a ysgrifennodd ‘What is this life if, full of care, we have no time to stand and stare.’",
   ["William Henry Davies was born in Newport in 1871. As a young man he crossed the Atlantic and lived as a tramp in the United States and Canada, riding freight trains, until in 1899 he lost his right leg trying to jump aboard one.",
    "Back in Britain he lived in lodging houses and taught himself to write poetry. The Autobiography of a Super-Tramp, in 1908, made him famous, and his poem ‘Leisure’ is one of the best loved in English. His statue in Newport shows him ‘standing and staring’."],
   ["Ganed William Henry Davies yng Nghasnewydd yn 1871. Yn ŵr ifanc croesodd yr Iwerydd a byw’n grwydryn yn yr Unol Daleithiau a Chanada, yn teithio ar drenau nwyddau, nes yn 1899 iddo golli ei goes dde wrth geisio neidio ar un.",
    "Yn ôl ym Mhrydain bu’n byw mewn llety rhad a dysgu ei hun i farddoni. Gwnaeth The Autobiography of a Super-Tramp, yn 1908, ef yn enwog, ac mae ei gerdd ‘Leisure’ ymhlith y mwyaf annwyl yn Saesneg. Mae ei gerflun yng Nghasnewydd yn ei ddangos yn ‘sefyll a syllu’."]),
 P("t-h-parry-williams", "modern", "1887–1975", "T. H. Parry-Williams", "T. H. Parry-Williams", "Poet of Rhyd-ddu", "Bardd Rhyd-ddu", "T._H._Parry-Williams", "words",
   "Poet and scholar from Rhyd-ddu who won both the Chair and the Crown at the same National Eisteddfod, twice.",
   "Bardd ac ysgolhaig o Ryd-ddu a enillodd y Gadair a’r Goron yn yr un Eisteddfod Genedlaethol, ddwywaith.",
   ["Thomas Herbert Parry-Williams was born in the schoolhouse at Rhyd-ddu under Yr Wyddfa. In 1912 he won both the Chair and the Crown at the National Eisteddfod in Wrexham, the first poet ever to do so, and in 1915 at Bangor he did it again.",
    "He became professor of Welsh at Aberystwyth, and his sonnets and rhymes, such as ‘Hon’ and ‘Llyn y Gader’, speak of the pull of the land of home in a plain, modern voice. His essays made the Welsh essay an art form."],
   ["Ganed Thomas Herbert Parry-Williams yn nhŷ’r ysgol yn Rhyd-ddu dan yr Wyddfa. Yn 1912 enillodd y Gadair a’r Goron yn Eisteddfod Genedlaethol Wrecsam, y bardd cyntaf erioed i wneud hynny, ac yn 1915 ym Mangor gwnaeth hynny eto.",
    "Daeth yn athro’r Gymraeg yn Aberystwyth, ac mae ei sonedau a’i rigymau, megis ‘Hon’ a ‘Llyn y Gader’, yn sôn am dynfa bro mebyd mewn llais plaen, modern. Gwnaeth ei ysgrifau’r ysgrif Gymraeg yn gelfyddyd."],
   first=("wales", "The first poet to win both the Chair and the Crown at one National Eisteddfod, 1912", "Y bardd cyntaf i ennill y Gadair a’r Goron yn yr un Eisteddfod Genedlaethol, 1912", 1912)),
 P("waldo-williams", "modern", "1904–1971", "Waldo Williams", "Waldo Williams", "Poet of Preseli", "Bardd y Preselau", "Waldo_Williams", "words",
   "Pacifist poet of Pembrokeshire whose one book, Dail Pren, is among the greatest in the Welsh language.",
   "Bardd heddychol o Sir Benfro y mae ei unig gyfrol, Dail Pren, ymhlith y mwyaf yn yr iaith Gymraeg.",
   ["Waldo Williams was born in Haverfordwest and grew up at Mynachlog-ddu under the Preseli hills, where he learned Welsh as a child. He was a teacher, a Quaker and a lifelong pacifist, and was imprisoned for refusing to pay income tax in protest at the Korean War.",
    "His collection Dail Pren, Leaves of a Tree, of 1956, holds poems such as ‘Mewn Dau Gae’, ‘Preseli’ and ‘Cofio’, full of the light of brotherhood and the love of his square mile. A memorial stone to him stands on the hill at Rhos-fach near Mynachlog-ddu."],
   ["Ganed Waldo Williams yn Hwlffordd a’i fagu ym Mynachlog-ddu dan fryniau’r Preselau, lle dysgodd Gymraeg yn blentyn. Roedd yn athro, yn Grynwr ac yn heddychwr gydol oes, a charcharwyd ef am wrthod talu treth incwm mewn protest yn erbyn Rhyfel Corea.",
    "Mae ei gyfrol Dail Pren, 1956, yn cynnwys cerddi fel ‘Mewn Dau Gae’, ‘Preseli’ a ‘Cofio’, yn llawn goleuni brawdgarwch a chariad at ei filltir sgwâr. Saif carreg goffa iddo ar y rhos yn Rhos-fach ger Mynachlog-ddu."]),
 P("roald-dahl", "modern", "1916–1990", "Roald Dahl", "Roald Dahl", "Storyteller from Llandaf", "Storïwr o Landaf", "Roald_Dahl", "words",
   "Born in Llandaf, Cardiff, to Norwegian parents, the world’s favourite children’s author: Charlie and the Chocolate Factory, Matilda, The BFG.",
   "Ganed yn Llandaf, Caerdydd, i rieni o Norwy; hoff awdur plant y byd: Charlie and the Chocolate Factory, Matilda, The BFG.",
   ["Roald Dahl was born in Llandaf in 1916 and was christened at the Norwegian Church in Cardiff Bay. He went to the cathedral school in Llandaf, and a sweetshop in the High Street gave him one of the stories in his memoir Boy.",
    "He was a fighter pilot in the Second World War, then a writer. His children’s books, among them James and the Giant Peach, Charlie and the Chocolate Factory, Fantastic Mr Fox, The BFG and Matilda, have sold more than three hundred million copies. Roald Dahl Plass in Cardiff Bay is named after him."],
   ["Ganed Roald Dahl yn Llandaf yn 1916 a’i fedyddio yn yr Eglwys Norwyaidd ym Mae Caerdydd. Aeth i ysgol yr eglwys gadeiriol yn Llandaf, a rhoddodd siop losin yn y Stryd Fawr un o’r straeon yn ei hunangofiant Boy iddo.",
    "Bu’n beilot ymladd yn yr Ail Ryfel Byd, ac yna’n awdur. Mae ei lyfrau plant, yn eu plith James and the Giant Peach, Charlie and the Chocolate Factory, Fantastic Mr Fox, The BFG a Matilda, wedi gwerthu dros dri chan miliwn o gopïau. Enwyd Plas Roald Dahl ym Mae Caerdydd ar ei ôl."]),
 P("raymond-williams", "modern", "1921–1988", "Raymond Williams", "Raymond Williams", "Thinker of the border", "Meddyliwr y ffin", "Raymond_Williams", "learning",
   "Railwayman’s son from Pandy who changed how the world studies culture, and wrote the novel Border Country.",
   "Mab gweithiwr rheilffordd o Bandy a newidiodd y ffordd y mae’r byd yn astudio diwylliant, ac a ysgrifennodd y nofel Border Country.",
   ["Raymond Williams was born at Pandy, near Abergavenny, the son of a railway signalman. He won a scholarship to Cambridge, fought in Normandy as a tank commander, and became professor of drama at Cambridge.",
    "His books, Culture and Society and Keywords among them, argued that ‘culture is ordinary’, the shared life of working people as much as fine art, and founded the field of cultural studies. His novel Border Country draws on his childhood in the Black Mountains. He called himself a Welsh European."],
   ["Ganed Raymond Williams ym Mhandy ger y Fenni, yn fab i signalwr rheilffordd. Enillodd ysgoloriaeth i Gaergrawnt, ymladdodd yn Normandi’n gadlywydd tanc, a daeth yn athro drama yng Nghaergrawnt.",
    "Dadleuai ei lyfrau, Culture and Society a Keywords yn eu plith, fod ‘diwylliant yn beth cyffredin’, bywyd cyffredin gweithwyr gymaint â chelfyddyd gain, a sefydlasant faes astudiaethau diwylliannol. Mae ei nofel Border Country yn tynnu ar ei blentyndod yn y Mynydd Du. Galwai ei hun yn Ewropead Cymreig."]),
 P("t-llew-jones", "modern", "1915–2009", "T. Llew Jones", "T. Llew Jones", "King of Welsh children’s books", "Brenin llenyddiaeth plant", "T._Llew_Jones", "words",
   "Teacher and poet of Pentre-cwrt who wrote over a hundred books for Welsh children, among them the adventures of Barti Ddu.",
   "Athro a bardd o Bentre-cwrt a ysgrifennodd dros gant o lyfrau i blant Cymru, yn eu plith anturiaethau Barti Ddu.",
   ["Thomas Llewelyn Jones was born at Pentre-cwrt in Carmarthenshire and became a village schoolmaster. He won the Chair of the National Eisteddfod twice, in 1958 and 1959.",
    "But his great gift was to Welsh children. In novels such as Trysor y Môr-ladron, Tân ar y Comin and Barti Ddu, and in poems learned by heart in every Welsh school, he gave generations of children stories of pirates, highwaymen and adventure in their own language."],
   ["Ganed Thomas Llewelyn Jones ym Mhentre-cwrt yn Sir Gaerfyrddin a daeth yn ysgolfeistr pentref. Enillodd Gadair yr Eisteddfod Genedlaethol ddwywaith, yn 1958 a 1959.",
    "Ond i blant Cymru y rhoddodd ei rodd fawr. Mewn nofelau fel Trysor y Môr-ladron, Tân ar y Comin a Barti Ddu, ac mewn cerddi a ddysgir ar gof ym mhob ysgol Gymraeg, rhoddodd straeon am fôr-ladron, lladron pen-ffordd ac antur i genedlaethau o blant yn eu hiaith eu hunain."]),
 P("gillian-clarke", "modern", "born 1937", "Gillian Clarke", "Gillian Clarke", "National Poet of Wales", "Bardd Cenedlaethol Cymru", "Gillian_Clarke", "words",
   "Cardiff-born poet whose poems are read in every school in Wales; National Poet of Wales from 2008 to 2016.",
   "Bardd o Gaerdydd y darllenir ei cherddi ym mhob ysgol yng Nghymru; Bardd Cenedlaethol Cymru o 2008 i 2016.",
   ["Gillian Clarke was born in Cardiff and lives on a smallholding in Ceredigion. Her poems of farm, family, history and the Welsh landscape have been studied by generations of schoolchildren, and she has translated poetry from Welsh.",
    "She was National Poet of Wales from 2008 to 2016, and in 2010 received the Queen’s Gold Medal for Poetry. She co-founded Tŷ Newydd, the writers’ centre at Llanystumdwy."],
   ["Ganed Gillian Clarke yng Nghaerdydd ac mae’n byw ar dyddyn yng Ngheredigion. Mae cenedlaethau o blant ysgol wedi astudio’i cherddi am fferm, teulu, hanes a thirwedd Cymru, ac mae wedi cyfieithu barddoniaeth o’r Gymraeg.",
    "Bu’n Fardd Cenedlaethol Cymru o 2008 i 2016, ac yn 2010 derbyniodd Fedal Aur y Frenhines am Farddoniaeth. Hi oedd un o sylfaenwyr Tŷ Newydd, y ganolfan i awduron yn Llanystumdwy."]),
 P("ken-follett", "modern", "born 1949", "Ken Follett", "Ken Follett", "Master storyteller", "Meistr y stori", "Ken_Follett", "words",
   "Cardiff-born novelist of Eye of the Needle and The Pillars of the Earth, one of the best-selling authors in the world.",
   "Nofelydd o Gaerdydd, awdur Eye of the Needle a The Pillars of the Earth, un o awduron mwyaf poblogaidd y byd.",
   ["Ken Follett was born in Cardiff in 1949 and worked as a reporter on the South Wales Echo before turning to fiction. Eye of the Needle, in 1978, a thriller of the Second World War, made his name.",
    "The Pillars of the Earth, the story of building a cathedral in the twelfth century, became one of the most read novels of its time. His books have sold more than 180 million copies in over thirty languages, and the story of a Welsh mining family runs through his Century trilogy."],
   ["Ganed Ken Follett yng Nghaerdydd yn 1949 a bu’n ohebydd ar y South Wales Echo cyn troi at ffuglen. Gwnaeth Eye of the Needle, yn 1978, nofel gyffro o’r Ail Ryfel Byd, ei enw.",
    "Daeth The Pillars of the Earth, hanes adeiladu eglwys gadeiriol yn y ddeuddegfed ganrif, yn un o nofelau mwyaf poblogaidd ei chyfnod. Mae ei lyfrau wedi gwerthu dros 180 miliwn o gopïau mewn dros ddeg ar hugain o ieithoedd, ac mae hanes teulu o lowyr o Gymru’n rhedeg drwy ei drioleg Century."]),
 P("gwyneth-lewis", "today", "born 1959", "Gwyneth Lewis", "Gwyneth Lewis", "The first National Poet of Wales", "Bardd Cenedlaethol cyntaf Cymru", "Gwyneth_Lewis", "words",
   "Poet in Welsh and English whose words, in letters two metres high, crown the Wales Millennium Centre.",
   "Bardd yn Gymraeg ac yn Saesneg y mae ei geiriau, mewn llythrennau dau fetr o uchder, yn coroni Canolfan Mileniwm Cymru.",
   ["Gwyneth Lewis was born in Cardiff and writes in both Welsh and English. In 2005 she was named the first National Poet of Wales.",
    "Her words are cut into the front of the Wales Millennium Centre in Cardiff Bay: ‘Creu gwir fel gwydr o ffwrnais awen’, creating truth like glass from the furnace of inspiration, and in English ‘In these stones horizons sing’. Her book Sunbathing in the Rain is a moving account of living through depression."],
   ["Ganed Gwyneth Lewis yng Nghaerdydd ac mae’n ysgrifennu yn Gymraeg ac yn Saesneg. Yn 2005 fe’i henwyd yn Fardd Cenedlaethol cyntaf Cymru.",
    "Mae ei geiriau wedi’u torri ar flaen Canolfan Mileniwm Cymru ym Mae Caerdydd: ‘Creu gwir fel gwydr o ffwrnais awen’, ac yn Saesneg ‘In these stones horizons sing’. Mae ei llyfr Sunbathing in the Rain yn hanes ingol o fyw drwy iselder."],
   first=("wales", "The first National Poet of Wales, 2005", "Bardd Cenedlaethol cyntaf Cymru, 2005", 2005)),
 P("mererid-hopwood", "today", "born 1964", "Mererid Hopwood", "Mererid Hopwood", "First woman to win the Chair", "Y fenyw gyntaf i ennill y Gadair", "Mererid_Hopwood", "words",
   "In 2001 she became the first woman to win the Chair of the National Eisteddfod, in its 825 years.",
   "Yn 2001 hi oedd y fenyw gyntaf i ennill Cadair yr Eisteddfod Genedlaethol, mewn 825 o flynyddoedd.",
   ["Mererid Hopwood was born in Cardiff and learned the strict-metre craft of cynghanedd as an adult. In 2001, at the National Eisteddfod in Denbigh, she won the Chair for an awdl on the theme of ‘Dadeni’, rebirth.",
    "She was the first woman ever to win the Chair, a prize first given by the Lord Rhys in 1176. She went on to win the Crown in 2003 and the Prose Medal in 2008, the first woman to win all three, and became Archdruid in 2024."],
   ["Ganed Mererid Hopwood yng Nghaerdydd a dysgodd grefft y gynghanedd yn oedolyn. Yn 2001, yn yr Eisteddfod Genedlaethol yn Ninbych, enillodd y Gadair am awdl ar y testun ‘Dadeni’.",
    "Hi oedd y fenyw gyntaf erioed i ennill y Gadair, gwobr a roddwyd gyntaf gan yr Arglwydd Rhys yn 1176. Aeth ymlaen i ennill y Goron yn 2003 a’r Fedal Ryddiaith yn 2008, y fenyw gyntaf i ennill y tair, a daeth yn Archdderwydd yn 2024."],
   first=("wales", "The first woman to win the Chair of the National Eisteddfod, 2001", "Y fenyw gyntaf i ennill Cadair yr Eisteddfod Genedlaethol, 2001", 2001)),
 P("augustus-john", "modern", "1878–1961", "Augustus John", "Augustus John", "Painter of Tenby", "Peintiwr Dinbych-y-pysgod", "Augustus_John", "art",
   "Tenby-born painter, the most famous portrait artist of his day, brother of Gwen John.",
   "Peintiwr a aned yn Ninbych-y-pysgod, peintiwr portreadau enwocaf ei oes, a brawd Gwen John.",
   ["Augustus John was born in Tenby in 1878 and trained at the Slade School in London, where he was hailed as the most gifted draughtsman of his generation. He lived a free, wandering life and travelled with the Romani people, whose language he learned.",
    "His portraits of the great figures of his age, among them Dylan Thomas, Lloyd George, T. E. Lawrence and W. B. Yeats, made him the most famous painter in Britain. His sister Gwen John is now as celebrated as he is."],
   ["Ganed Augustus John yn Ninbych-y-pysgod yn 1878 a hyfforddodd yn Ysgol y Slade yn Llundain, lle’i cyfrifid yn ddarlunydd mwyaf dawnus ei genhedlaeth. Bu fyw bywyd rhydd, crwydrol, a theithio gyda’r Sipsiwn, a dysgodd eu hiaith.",
    "Gwnaeth ei bortreadau o ffigurau mawr ei oes, Dylan Thomas, Lloyd George, T. E. Lawrence a W. B. Yeats yn eu plith, ef yn beintiwr enwocaf Prydain. Mae ei chwaer Gwen John bellach yr un mor enwog ag yntau."]),
 P("clough-williams-ellis", "modern", "1883–1978", "Sir Clough Williams-Ellis", "Syr Clough Williams-Ellis", "Creator of Portmeirion", "Crëwr Portmeirion", "Clough_Williams-Ellis", "art",
   "Architect who spent fifty years building the fairy-tale village of Portmeirion and campaigned to protect the landscape of Wales.",
   "Pensaer a dreuliodd hanner can mlynedd yn adeiladu pentref hudol Portmeirion ac a ymgyrchodd i warchod tirwedd Cymru.",
   ["Clough Williams-Ellis came of an old family of Plas Brondanw in Meirionnydd. In 1925 he bought a wild peninsula on the Dwyryd estuary and began to build Portmeirion, an Italianate village of colour and fantasy, to show that building could enhance a beautiful place rather than spoil it.",
    "He worked on it until 1976. He campaigned all his life for the countryside, helped found the Council for the Protection of Rural Wales and fought for national parks. Portmeirion was the setting of the television series The Prisoner."],
   ["Deuai Clough Williams-Ellis o hen deulu Plas Brondanw ym Meirionnydd. Yn 1925 prynodd benrhyn gwyllt ar aber y Ddwyryd a dechrau adeiladu Portmeirion, pentref Eidalaidd ei naws, yn llawn lliw a ffantasi, i ddangos y gallai adeiladu harddu lle hardd yn hytrach na’i ddifetha.",
    "Bu wrthi tan 1976. Ymgyrchodd ar hyd ei oes dros gefn gwlad, helpodd i sefydlu Ymgyrch Diogelu Cymru Wledig a brwydrodd dros barciau cenedlaethol. Portmeirion oedd lleoliad y gyfres deledu The Prisoner."]),
 P("kyffin-williams", "modern", "1918–2006", "Sir Kyffin Williams", "Syr Kyffin Williams", "Painter of Eryri and Môn", "Peintiwr Eryri a Môn", "Kyffin_Williams", "art",
   "Llangefni painter whose thick, dark, palette-knife landscapes of the mountains and coast of the north are loved across Wales.",
   "Peintiwr o Langefni y mae ei dirluniau tywyll, trwchus, â chyllell balet, o fynyddoedd ac arfordir y gogledd yn annwyl drwy Gymru gyfan.",
   ["John Kyffin Williams was born in Llangefni in 1918. When epilepsy ended his army career, a doctor told him he should take up art, and he went to the Slade.",
    "For sixty years he painted the mountains of Eryri, the farms and farmers of Môn and the stormy coast, in thick paint laid on with a palette knife, and in 1968 he painted the Welsh in Patagonia. He was the most loved Welsh painter of his time, and Oriel Kyffin Williams at Oriel Môn in Llangefni holds hundreds of his works."],
   ["Ganed John Kyffin Williams yn Llangefni yn 1918. Pan ddaeth epilepsi â’i yrfa yn y fyddin i ben, dywedodd meddyg wrtho am droi at gelf, ac aeth i’r Slade.",
    "Am drigain mlynedd peintiodd fynyddoedd Eryri, ffermydd a ffermwyr Môn a’r arfordir stormus, mewn paent trwchus wedi’i osod â chyllell balet, ac yn 1968 peintiodd Gymry Patagonia. Ef oedd peintiwr mwyaf annwyl Cymru yn ei oes, ac mae Oriel Kyffin Williams yn Oriel Môn, Llangefni, yn cadw cannoedd o’i weithiau."]),
 P("bertrand-russell", "modern", "1872–1970", "Bertrand Russell", "Bertrand Russell", "Philosopher of Trellech and Penrhyndeudraeth", "Athronydd Tryleg a Phenrhyndeudraeth", "Bertrand_Russell", "learning",
   "Born at Trellech in Monmouthshire, one of the greatest philosophers of the age and a Nobel prize winner, he spent his last years at Penrhyndeudraeth.",
   "Ganed yn Nhryleg yn Sir Fynwy; un o athronwyr mwyaf yr oes ac enillydd gwobr Nobel, a dreuliodd ei flynyddoedd olaf ym Mhenrhyndeudraeth.",
   ["Bertrand Russell was born at Ravenscroft, Trellech, in Monmouthshire in 1872. With Alfred North Whitehead he wrote Principia Mathematica, which tried to build all of mathematics on logic, and he was one of the founders of modern philosophy.",
    "He won the Nobel Prize for Literature in 1950, campaigned against war all his life and was the first president of the Campaign for Nuclear Disarmament. He spent his last years at Plas Penrhyn above Porthmadog and died there in 1970, aged ninety-seven."],
   ["Ganed Bertrand Russell yn Ravenscroft, Tryleg, yn Sir Fynwy yn 1872. Gydag Alfred North Whitehead ysgrifennodd Principia Mathematica, a geisiodd adeiladu’r holl fathemateg ar resymeg, ac roedd yn un o sylfaenwyr athroniaeth fodern.",
    "Enillodd Wobr Nobel am Lenyddiaeth yn 1950, ymgyrchodd yn erbyn rhyfel ar hyd ei oes a bu’n llywydd cyntaf yr Ymgyrch dros Ddiarfogi Niwclear. Treuliodd ei flynyddoedd olaf ym Mhlas Penrhyn uwchben Porthmadog a bu farw yno yn 1970, yn saith a phedwar ugain oed."]),
 P("ernest-jones", "modern", "1879–1958", "Ernest Jones", "Ernest Jones", "Who brought psychoanalysis to the English-speaking world", "Y gŵr a ddaeth â seicdreiddio i’r byd Saesneg", "Ernest_Jones", "science",
   "Doctor from Gowerton, the first English-speaking psychoanalyst, who rescued Sigmund Freud from the Nazis in 1938.",
   "Meddyg o Dre-gŵyr, y seicdreiddiwr Saesneg ei iaith cyntaf, a achubodd Sigmund Freud rhag y Natsïaid yn 1938.",
   ["Ernest Jones was born in Gowerton near Swansea and trained as a doctor in Cardiff and London. He met Sigmund Freud in 1908 and became his closest friend outside Vienna and the first psychoanalyst in the English-speaking world.",
    "He founded the British Psychoanalytical Society and the International Journal of Psychoanalysis. In 1938, when the Nazis took Austria, he flew to Vienna and won permission for Freud and his family to settle in London. He later wrote Freud’s great biography. He was proud of Gower all his life and is buried at Cheriton."],
   ["Ganed Ernest Jones yn Nhre-gŵyr ger Abertawe a hyfforddodd yn feddyg yng Nghaerdydd a Llundain. Cyfarfu â Sigmund Freud yn 1908 a daeth yn gyfaill agosaf iddo y tu allan i Fienna ac yn seicdreiddiwr cyntaf y byd Saesneg.",
    "Sefydlodd Gymdeithas Seicdreiddiol Prydain a’r International Journal of Psychoanalysis. Yn 1938, pan gipiodd y Natsïaid Awstria, hedfanodd i Fienna ac ennill caniatâd i Freud a’i deulu ymgartrefu yn Llundain. Ysgrifennodd gofiant mawr Freud yn ddiweddarach. Roedd yn falch o Benrhyn Gŵyr ar hyd ei oes ac mae wedi’i gladdu yn Cheriton."],
   first=("world", "The first psychoanalyst in the English-speaking world, 1908", "Seicdreiddiwr cyntaf y byd Saesneg, 1908", 1908)),
 P("thomas-lewis", "modern", "1881–1945", "Sir Thomas Lewis", "Syr Thomas Lewis", "Pioneer of the heart trace", "Arloeswr olrhain y galon", "Thomas_Lewis_(cardiologist)", "science",
   "Cardiff-born doctor who first used the electrocardiogram to read the rhythm of the heart, founding modern cardiology.",
   "Meddyg o Gaerdydd a ddefnyddiodd yr electrocardiogram gyntaf i ddarllen rhythm y galon, gan sefydlu cardioleg fodern.",
   ["Thomas Lewis was born in Cardiff in 1881 and studied medicine there and at University College Hospital in London. He was one of the first doctors to take up the new electrocardiograph, which traced the electrical beat of the heart.",
    "In 1909 he showed that the irregular pulse known as atrial fibrillation could be seen and diagnosed on the trace, and his books taught the world how to read heart rhythms. He is honoured as a founder of modern cardiology, and was one of the first to study medicine by careful experiment on patients."],
   ["Ganed Thomas Lewis yng Nghaerdydd yn 1881 ac astudiodd feddygaeth yno ac yn Ysbyty Coleg y Brifysgol yn Llundain. Roedd yn un o’r meddygon cyntaf i fabwysiadu’r electrocardiograff newydd, a olrheiniai guriad trydanol y galon.",
    "Yn 1909 dangosodd y gellid gweld a chanfod y curiad afreolaidd a elwir yn ffibriliad atrïaidd ar yr olrhain, a dysgodd ei lyfrau i’r byd sut i ddarllen rhythmau’r galon. Fe’i hanrhydeddir yn un o sylfaenwyr cardioleg fodern."],
   first=("world", "First diagnosed atrial fibrillation on the electrocardiogram, 1909", "Y cyntaf i ganfod ffibriliad atrïaidd ar yr electrocardiogram, 1909", 1909)),
 P("evan-james-williams", "modern", "1903–1945", "E. J. Williams", "E. J. Williams", "Physicist of Llanwenog", "Ffisegydd Llanwenog", "Evan_James_Williams", "science",
   "Physicist from Cwmsychbant in Ceredigion who took the first photograph of a subatomic particle decaying, in 1940.",
   "Ffisegydd o Gwmsychbant yng Ngheredigion a dynnodd y ffotograff cyntaf o ronyn isatomig yn dadfeilio, yn 1940.",
   ["Evan James Williams was born at Cwmsychbant, Llanwenog, and studied at Swansea, Manchester and Cambridge, where he worked with Rutherford and Bohr. He became professor of physics at Aberystwyth and spoke Welsh in his laboratory.",
    "In 1940, with G. E. Roberts, he used a cloud chamber at Aberystwyth to take the first photograph of the decay of a muon, a particle from cosmic rays, a landmark in particle physics. In the Second World War he led scientific research that helped win the battle against the U-boats."],
   ["Ganed Evan James Williams yng Nghwmsychbant, Llanwenog, ac astudiodd yn Abertawe, Manceinion a Chaergrawnt, lle bu’n gweithio gyda Rutherford a Bohr. Daeth yn athro ffiseg yn Aberystwyth a siaradai Gymraeg yn ei labordy.",
    "Yn 1940, gyda G. E. Roberts, defnyddiodd siambr gwmwl yn Aberystwyth i dynnu’r ffotograff cyntaf o fwon yn dadfeilio, gronyn o’r pelydrau cosmig, carreg filltir mewn ffiseg gronynnau. Yn yr Ail Ryfel Byd arweiniodd ymchwil wyddonol a helpodd ennill y frwydr yn erbyn y llongau tanfor."],
   first=("world", "The first photograph of a subatomic particle decaying, Aberystwyth 1940", "Y ffotograff cyntaf o ronyn isatomig yn dadfeilio, Aberystwyth 1940", 1940)),
 P("edward-bowen", "modern", "1911–1991", "Edward ‘Taffy’ Bowen", "Edward ‘Taffy’ Bowen", "Father of airborne radar", "Tad radar yn yr awyr", "Edward_George_Bowen", "science",
   "Swansea physicist who built the first radar small enough to fly in an aircraft, then pioneered radio astronomy in Australia.",
   "Ffisegydd o Abertawe a adeiladodd y radar cyntaf a oedd yn ddigon bach i hedfan mewn awyren, ac a arloesodd seryddiaeth radio yn Awstralia wedyn.",
   ["Edward George Bowen was born in Swansea, the son of a steelworker, and studied at Swansea and London. In 1935 he joined Robert Watson-Watt’s team building radar, and was given the hardest task: a set small enough to go in an aeroplane.",
    "By 1937 his airborne radar had found ships at sea, and it went on to help the RAF find enemy bombers at night and the navy hunt submarines. In 1940 he crossed the Atlantic with the cavity magnetron, the secret that let America build radar. After the war he led radio astronomy in Australia and helped build the Parkes telescope that received the pictures of the Moon landing."],
   ["Ganed Edward George Bowen yn Abertawe, yn fab i weithiwr dur, ac astudiodd yn Abertawe a Llundain. Yn 1935 ymunodd â thîm Robert Watson-Watt a oedd yn adeiladu radar, a chael y dasg anoddaf: set ddigon bach i fynd mewn awyren.",
    "Erbyn 1937 roedd ei radar awyr wedi canfod llongau ar y môr, ac aeth ymlaen i helpu’r Awyrlu i ganfod awyrennau bomio’r gelyn liw nos a’r llynges i hela llongau tanfor. Yn 1940 croesodd yr Iwerydd gyda’r magnetron ceudod, y gyfrinach a alluogodd America i adeiladu radar. Wedi’r rhyfel arweiniodd seryddiaeth radio yn Awstralia a helpu adeiladu telesgop Parkes a dderbyniodd luniau’r glaniad ar y Lleuad."],
   first=("world", "The first radar small enough to fly in an aircraft, 1937", "Y radar cyntaf a oedd yn ddigon bach i hedfan mewn awyren, 1937", 1937)),
 P("donald-davies", "modern", "1924–2000", "Donald Davies", "Donald Davies", "Inventor of packet switching", "Dyfeisiwr newid pecynnau", "Donald_Davies", "science",
   "Born in Treorchy, he invented packet switching in 1965, the method by which every message, page and video crosses the internet.",
   "Ganed yn Nhreorci; dyfeisiodd newid pecynnau yn 1965, y dull y mae pob neges, tudalen a fideo yn croesi’r rhyngrwyd drwyddo.",
   ["Donald Watts Davies was born in Treorchy in the Rhondda in 1924. His father, a clerk at a coal mine, died when he was a baby, and his mother moved the family to Portsmouth. He studied physics and mathematics and worked with Alan Turing on one of the first computers.",
    "In 1965 at the National Physical Laboratory he had the idea of breaking data into small blocks, which he called packets, each sent separately through a network and put back together at the end. He built the first network to use it. Packet switching is how the internet works: every email, web page and video call travels in packets."],
   ["Ganed Donald Watts Davies yn Nhreorci yn y Rhondda yn 1924. Bu farw ei dad, clerc mewn pwll glo, pan oedd yn faban, a symudodd ei fam y teulu i Portsmouth. Astudiodd ffiseg a mathemateg a bu’n gweithio gydag Alan Turing ar un o’r cyfrifiaduron cyntaf.",
    "Yn 1965 yn y Labordy Ffisegol Cenedlaethol cafodd y syniad o dorri data’n flociau bach, a alwodd yn becynnau, pob un yn cael ei anfon ar wahân drwy rwydwaith a’u rhoi’n ôl at ei gilydd ar y diwedd. Adeiladodd y rhwydwaith cyntaf i’w ddefnyddio. Dyma sut mae’r rhyngrwyd yn gweithio: mae pob e-bost, tudalen we a galwad fideo yn teithio mewn pecynnau."],
   first=("world", "Invented packet switching, the basis of the internet, 1965", "Dyfeisiodd newid pecynnau, sail y rhyngrwyd, 1965", 1965)),
 P("tom-parry-jones", "modern", "1935–2013", "Tom Parry Jones", "Tom Parry Jones", "Inventor of the breathalyser", "Dyfeisiwr y prawf anadl", "Tom_Parry_Jones", "science",
   "Scientist from Carmel in Môn who made the first electronic breathalyser in 1974 and saved countless lives on the roads.",
   "Gwyddonydd o Garmel ym Môn a wnaeth y prawf anadl electronig cyntaf yn 1974 ac a achubodd fywydau di-rif ar y ffyrdd.",
   ["Tom Parry Jones was born at Carmel near Llanerchymedd in Môn and studied chemistry at Bangor. Lecturing in Cardiff, he worked out how a fuel cell could measure the alcohol in a person’s breath accurately.",
    "In 1974 his company, Lion Laboratories in Barry, produced the Alcolmeter, the world’s first electronic breathalyser. Police forces across the world adopted it, and deaths from drink-driving fell sharply. His company won the Queen’s Award for Technology in 1980."],
   ["Ganed Tom Parry Jones yng Ngharmel ger Llannerch-y-medd ym Môn ac astudiodd gemeg ym Mangor. Tra’n darlithio yng Nghaerdydd, gweithiodd allan sut y gallai cell danwydd fesur yr alcohol yn anadl rhywun yn fanwl gywir.",
    "Yn 1974 cynhyrchodd ei gwmni, Lion Laboratories yn y Barri, yr Alcolmeter, prawf anadl electronig cyntaf y byd. Mabwysiadodd heddluoedd ledled y byd ef, a syrthiodd marwolaethau o yfed a gyrru’n sylweddol. Enillodd ei gwmni Wobr y Frenhines am Dechnoleg yn 1980."],
   first=("world", "The first electronic breathalyser, 1974", "Y prawf anadl electronig cyntaf, 1974", 1974)),
 P("john-meurig-thomas", "modern", "1932–2020", "Sir John Meurig Thomas", "Syr John Meurig Thomas", "Chemist of Llanelli", "Cemegydd o Lanelli", "John_Meurig_Thomas", "science",
   "Miner’s son from Llanelli whose work on catalysts made chemistry cleaner, and who led the Royal Institution. A mineral is named after him.",
   "Mab glöwr o Lanelli y gwnaeth ei waith ar gatalyddion gemeg yn lanach, ac a arweiniodd y Sefydliad Brenhinol. Enwyd mwyn ar ei ôl.",
   ["John Meurig Thomas was born in Llanelli, a miner’s son, and studied at Swansea. He became professor of chemistry at Aberystwyth, then at Cambridge, and director of the Royal Institution in London, where Faraday had worked.",
    "His discoveries about how solid catalysts work led to cleaner, greener ways of making chemicals and fuels, and he was among the most cited chemists in the world. The mineral meurigite is named after him. He never lost his Welsh, or his love of the poets."],
   ["Ganed John Meurig Thomas yn Llanelli, yn fab i löwr, ac astudiodd yn Abertawe. Daeth yn athro cemeg yn Aberystwyth, yna yng Nghaergrawnt, ac yn gyfarwyddwr y Sefydliad Brenhinol yn Llundain, lle bu Faraday’n gweithio.",
    "Arweiniodd ei ddarganfyddiadau am sut mae catalyddion solet yn gweithio at ffyrdd glanach a gwyrddach o wneud cemegion a thanwydd, ac roedd ymhlith y cemegwyr a ddyfynnid amlaf yn y byd. Enwyd y mwyn meurigite ar ei ôl. Ni chollodd ei Gymraeg erioed, na’i gariad at y beirdd."]),
 P("clive-granger", "modern", "1934–2009", "Sir Clive Granger", "Syr Clive Granger", "Nobel economist", "Economegydd Nobel", "Clive_Granger", "learning",
   "Swansea-born economist who won the Nobel Prize in 2003 for methods now used to study prices, markets and climate across the world.",
   "Economegydd a aned yn Abertawe a enillodd Wobr Nobel yn 2003 am ddulliau a ddefnyddir heddiw i astudio prisiau, marchnadoedd a’r hinsawdd ledled y byd.",
   ["Clive Granger was born in Swansea in 1934 and studied mathematics at Nottingham. He became a professor at the University of California, San Diego, and one of the leading statisticians of economics.",
    "His ideas, Granger causality and cointegration, gave economists ways to tell whether one trend really drives another. They are used in finance, in forecasting and in climate science, and in 2003 they won him the Nobel Prize for Economics."],
   ["Ganed Clive Granger yn Abertawe yn 1934 ac astudiodd fathemateg yn Nottingham. Daeth yn athro ym Mhrifysgol California, San Diego, ac yn un o ystadegwyr blaenaf economeg.",
    "Rhoddodd ei syniadau, achosiaeth Granger a chyd-integreiddio, ffyrdd i economegwyr ddweud a yw un duedd yn wir yn gyrru un arall. Fe’u defnyddir mewn cyllid, mewn rhagolygon ac yng ngwyddor hinsawdd, ac yn 2003 enillasant Wobr Nobel am Economeg iddo."]),
 P("brian-josephson", "modern", "born 1940", "Brian Josephson", "Brian Josephson", "Nobel physicist", "Ffisegydd Nobel", "Brian_Josephson", "science",
   "Cardiff-born physicist who at 22 predicted the Josephson effect, used in the world’s most sensitive instruments, and won the Nobel Prize at 33.",
   "Ffisegydd a aned yng Nghaerdydd a ragfynegodd, yn 22 oed, effaith Josephson, a ddefnyddir yn offer mwyaf sensitif y byd, ac a enillodd Wobr Nobel yn 33.",
   ["Brian Josephson was born in Cardiff in 1940 and went to Cardiff High School before studying at Cambridge. In 1962, as a 22-year-old research student, he predicted that an electric current could flow without any voltage between two superconductors separated by a thin barrier.",
    "The Josephson effect was soon proved, and the Josephson junction is now at the heart of the most sensitive magnetic detectors on earth, of the international standard for the volt and of quantum computers. He won the Nobel Prize for Physics in 1973."],
   ["Ganed Brian Josephson yng Nghaerdydd yn 1940 ac aeth i Ysgol Uwchradd Caerdydd cyn astudio yng Nghaergrawnt. Yn 1962, yn fyfyriwr ymchwil dwy ar hugain oed, rhagfynegodd y gallai cerrynt trydan lifo heb unrhyw foltedd rhwng dau uwchddargludydd wedi’u gwahanu gan rwystr tenau.",
    "Profwyd effaith Josephson yn fuan, ac mae cyswllt Josephson heddiw wrth galon synwyryddion magnetig mwyaf sensitif y byd, safon ryngwladol y folt a chyfrifiaduron cwantwm. Enillodd Wobr Nobel am Ffiseg yn 1973."],
   first=("world", "Predicted the Josephson effect, 1962: Nobel Prize 1973", "Rhagfynegodd effaith Josephson, 1962: Gwobr Nobel 1973", 1962)),
 P("rowan-williams", "today", "born 1950", "Rowan Williams", "Rowan Williams", "Archbishop of Canterbury", "Archesgob Caergaint", "Rowan_Williams", "faith",
   "Welsh-speaking theologian and poet from Swansea, Archbishop of Wales and then Archbishop of Canterbury from 2002 to 2012.",
   "Diwinydd a bardd Cymraeg o Abertawe, Archesgob Cymru ac yna Archesgob Caergaint o 2002 i 2012.",
   ["Rowan Williams was born in Swansea in 1950, grew up in a Welsh-speaking family and studied at Cambridge and Oxford, becoming one of the most respected theologians in the world. He was Bishop of Monmouth and then Archbishop of Wales from 1999.",
    "In 2002 he became Archbishop of Canterbury, leading the worldwide Anglican Communion for ten years. He writes poetry in English and translates Welsh poets, among them Waldo Williams and Ann Griffiths, and was made a druid of the Gorsedd."],
   ["Ganed Rowan Williams yn Abertawe yn 1950, a’i fagu mewn teulu Cymraeg ac astudiodd yng Nghaergrawnt a Rhydychen, gan ddod yn un o ddiwinyddion mwyaf uchel eu parch y byd. Bu’n Esgob Mynwy ac yna’n Archesgob Cymru o 1999.",
    "Yn 2002 daeth yn Archesgob Caergaint, yn arwain y Cymundeb Anglicanaidd byd-eang am ddeng mlynedd. Mae’n barddoni yn Saesneg ac yn cyfieithu beirdd Cymraeg, Waldo Williams ac Ann Griffiths yn eu plith, ac fe’i gwnaed yn dderwydd yr Orsedd."]),
 P("tori-james", "today", "born 1981", "Tori James", "Tori James", "To the top of the world", "I ben y byd", "Tori_James", "explore",
   "Pembrokeshire adventurer who in 2007 became the first Welsh woman to climb Everest.",
   "Anturiaethwraig o Sir Benfro ac yn 2007 hi oedd y fenyw gyntaf o Gymru i ddringo Everest.",
   ["Tori James grew up on a farm in Pembrokeshire. Before Everest she had raced across the Arctic in a team challenge to the magnetic North Pole.",
    "On 16 May 2007, at the age of twenty-five, she stood on the summit of Everest, the first Welsh woman to do so, and the youngest British woman at the time. She carried a Welsh flag to the top of the world, and now encourages young people to take on their own adventures."],
   ["Magwyd Tori James ar fferm yn Sir Benfro. Cyn Everest roedd wedi rasio ar draws yr Arctig mewn her tîm i Begwn Magnetig y Gogledd.",
    "Ar 16 Mai 2007, yn bump ar hugain oed, safodd ar gopa Everest, y fenyw gyntaf o Gymru i wneud hynny, a’r fenyw ieuengaf o Brydain ar y pryd. Cariodd ddraig goch i ben y byd, ac mae’n annog pobl ifanc heddiw i fentro ar eu hanturiaethau eu hunain."],
   first=("wales", "The first Welsh woman to climb Everest, 2007", "Y fenyw gyntaf o Gymru i ddringo Everest, 2007", 2007)),
]
